body{font-family:'Tajawal','DejaVu Sans',sans-serif;line-height:1.55}.brand-cell{white-space:nowrap}.brand-copy{margin-right:12px;line-height:1.5;white-space:normal}.brand-name{display:block;unicode-bidi:isolate}.brand-name-ar{font-size:13px;text-align:right}.brand-name-en{font-size:9px;color:#596579;text-align:right}.brand-contact{direction:ltr;unicode-bidi:isolate;white-space:nowrap}.document-header[dir=ltr] .title-cell{text-align:left}.document-header[dir=ltr] .brand-cell{text-align:right}.document-header[dir=ltr] .brand-copy{margin-left:0;margin-right:12px}.document-title{font-weight:700}.summary .value,.amount-value{direction:ltr;unicode-bidi:isolate}.section-title{padding-right:7px;border-right:3px solid #c8a878}.data thead{display:table-header-group}.data tfoot{display:table-row-group}.data tr,.info-table tr,.summary tr,.hero tr{page-break-inside:avoid}.data td,.data th{vertical-align:middle;word-break:break-word}.data td[dir=ltr],.data .money{white-space:nowrap}.hero,.summary,.info-table,.amount-panel,.notes,.voucher-grid,.voucher-verification{page-break-inside:avoid}.section-title{page-break-after:avoid}.document-footer{page-break-inside:avoid}.empty-state,.data td[colspan]{padding:18px 8px;color:#7d8797;text-align:center}
.voucher-document{width:196mm;max-width:196mm;min-height:0;margin:0 auto;padding:0 3mm 2mm}.voucher-document .top-gradient{margin-left:-3mm;margin-right:-3mm;margin-bottom:4mm}.voucher-document .document-header{margin-bottom:6px}.voucher-document .document-header td{padding-bottom:7px}.voucher-document .brand-logo{width:68px;max-height:42px}.voucher-document .document-title{font-size:17px}.voucher-document .hero{margin-bottom:7px}.voucher-document .hero td{padding:8px 11px}.voucher-document .voucher-grid{direction:ltr;border-spacing:7px 0}.voucher-document .voucher-grid>tbody>tr>td{direction:rtl}.voucher-document .voucher-details{width:66%}.voucher-document .voucher-amount{width:34%;padding:11px 8px}.voucher-document .voucher-amount .amount-value{font-size:21px}.voucher-document .info-table{margin-bottom:7px}.voucher-document .info-table td{padding:5px 7px}.voucher-document .section-title{margin:7px 0 4px}.voucher-document .notes{min-height:30px;padding:7px}.voucher-document .voucher-verification{margin-top:6px}.voucher-document .voucher-verification .qr-cell{width:24%;text-align:left}.voucher-document .voucher-verification .barcode-cell{width:76%;text-align:center}.voucher-document .document-footer{margin-top:3px}
.bilingual-name{display:inline-block;max-width:100%;unicode-bidi:isolate}.bilingual-name-ar,.bilingual-name-en{display:block;line-height:1.25}.bilingual-name-ar{text-align:right}.bilingual-name-en{text-align:left;font-family:DejaVu Sans,sans-serif;font-size:.82em;direction:ltr;unicode-bidi:isolate}
</style>
<style>.voucher-verification{width:100%;margin-top:9px;border:1px solid #e0e5ec;border-radius:10px;background:#fff;page-break-inside:avoid;direction:ltr}.voucher-verification td{vertical-align:middle;padding:7px}.voucher-verification .qr-cell{width:86px;text-align:center}.voucher-verification .qr-cell img{display:block;width:76px;height:76px;margin:auto}.voucher-verification .barcode-cell{text-align:center;direction:ltr}.voucher-verification .barcode-cell img{display:block;width:280px;max-width:100%;height:52px;margin:0 auto 3px}.voucher-verification .barcode-cell strong{display:block;font-family:monospace;font-size:10px;letter-spacing:1px}.voucher-verification .barcode-cell span{display:block;margin-top:2px;color:#7d8797;font-size:7px}/* A5 and A4 widths come from the page content area, including its padding. */
.statement-document .summary{border-spacing:3px 0}
.statement-document .summary td{padding:7px 3px}
.statement-document .summary .value{font-size:10px;white-space:normal}
.statement-document .data{table-layout:fixed}
.statement-document .data th,.statement-document .data td{font-size:9px;padding:5px 3px;overflow-wrap:break-word}
.statement-document .data th:nth-child(1){width:4%}
.statement-document .data th:nth-child(2){width:11%}
.statement-document .data th:nth-child(3){width:13%}
.statement-document .data th:nth-child(4){width:12%}
.statement-document .data th:nth-child(9){width:16%}
.statement-document .data td:nth-child(2){white-space:nowrap;font-size:8px}
.statement-document .data td:nth-child(n+5):nth-child(-n+8){direction:ltr;font-size:8px}
@media print{
    html,body{margin:0!important;background:#fff!important}
    .document,.document:not(.voucher-document),.voucher-document{
        width:auto!important;max-width:none!important;min-height:0!important;
        margin:0 auto!important;padding:0 3mm!important;box-shadow:none!important;
    }
    .top-gradient,.voucher-document .top-gradient{
        height:5px;margin:0 -3mm 4mm!important;
    }
    .document-header{page-break-inside:avoid}
    .actions{display:none!important}
    /* Keep company details out of table pagination and above the PDF page numbers. */
    .document-footer{position:fixed;bottom:-5mm;left:0;right:0;width:100%;margin:0!important;padding-top:4px}
    .voucher-document .voucher-grid{border-spacing:5px 0}
    .voucher-document .voucher-verification td{padding:4px}
    .voucher-document .voucher-verification .qr-cell img{width:60px;height:60px}
    .voucher-document .voucher-verification .barcode-cell img{width:240px;height:38px}
    .statement-document .document-header{margin-bottom:8px}
    .statement-document .hero{margin-bottom:8px}
    .statement-document .hero td{padding:8px 10px}
    .statement-document .info-table{margin-bottom:8px}
    .statement-document .info-table td{padding:5px 7px}
}
